import { ImageStyle } from "@/lib/media/settings";
import { stylePreviewSrc } from "@/lib/media/style-previews";

/**
 * A style is a visual choice, so it is shown, not described. What each card
 * shows is a REAL sample of that style, generated by the production image path
 * and committed under `public/style-previews/` — see `lib/media/style-previews.ts`.
 */
export function ImageStylePreview({ style }: { style: ImageStyle }) {
  if (style === "custom") {
    return (
      <div className="flex h-full w-full items-center justify-center bg-muted/60 text-3xl font-light text-muted-foreground">
        +
      </div>
    );
  }

  return (
    // eslint-disable-next-line @next/next/no-img-element -- a committed static
    // thumbnail sized by its container; the optimizer adds nothing here.
    <img
      src={stylePreviewSrc(style)}
      alt=""
      loading="lazy"
      className="h-full w-full object-cover"
    />
  );
}
